const D=[["nangman_ipjujang_jeonse_1_month.png", ""], ["nangman_ipjujang_jeonse_2_sigi.png", ""], ["nangman_ipjujang_jeonse_3_geupmae.png", ""], ["nangman_ipjujang_jeonse_4_wolse.png", ""], ["nangman_ipjujang_jeonse_5_segyo.png", ""], ["nangman_ipjujang_jeonse_6_danji.png", ""]];const f=[...document.querySelectorAll("iframe")].find(x=>{try{return x.contentDocument&&x.contentDocument.body.isContentEditable}catch(e){return false}});const dt=new DataTransfer();D.forEach(([n,b])=>{const a=Uint8Array.from(atob(b),c=>c.charCodeAt(0));dt.items.add(new File([a],n,{type:"image/png"}))});f.contentDocument.body.dispatchEvent(new DragEvent("drop",{dataTransfer:dt,bubbles:true,cancelable:true}));dt.files.length